        ex: { code: "const name = \"  ada lovelace  \";\nconst clean = name.trim();\nconsole.log(clean.toUpperCase());\nconsole.log(clean.length);\nconsole.log(clean.slice(0, 3));\nconsole.log(clean.includes(\"love\"));\nconsole.log(`${clean} wrote the first program.`);",
          walk: ["Line 1: a name with spaces at both ends.", "Line 2: trim removes them.", "Line 3: ADA LOVELACE.", "Line 4: 12 characters.", "Line 5: ada.", "Line 6: true — the word is inside.", "Line 7: a template literal sentence."] },
        mistake: "Using ${ } inside normal quotes. \"Score: ${score}\" prints those characters literally; only backtick strings fill in values: `Score: ${score}`."
